    /// <summary>
    /// Write the record
    /// </summary>
    public void write()
    {
        METInventLocation metInventLocation = this.cursor();

        if (metInventLocation.InventLocation)
        {
            next Write();
        }
    }

    /// <summary>
    /// Validate the record
    /// </summary>
    /// <returns>Result of the validation</returns>
    public boolean validatewrite()
    {
        boolean ret = true;
        
        METInventLocation metInventLocation = this.cursor();

        if (metInventLocation.InventLocation)
        {
            ret = next validatewrite();
        }

        return ret;
    }
